import asyncio
from backend.app.models import Task
from backend.app.utils import enrich_task


async def loader(task_id):
    return {'id': task_id, 'priority': 'high'}


def test_enrich_task_awaits_loader():
    task = Task(id=7, title='Async')
    result = asyncio.run(enrich_task(task, loader))
    assert result['details'] == {'id': 7, 'priority': 'high'}
